; ---------------------------------------------------------------
; void __near__ add_step (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_add_step: near

.segment	"CODE"

;
; if(step_button_lockout > 0){
;
	lda     _step_button_lockout
;
; return; //still in lockout period
;
	beq     L51B7
;
; }
;
	rts
;
; update_steps_per_minute(); // calculate SPM before resetting the timer
;
L51B7:	jsr     _update_steps_per_minute
;
; sprite_timer = 0; //used for animation
;
	lda     #$00
	sta     _sprite_timer
;
; velocity += 100;
;
	lda     #$64
	clc
	adc     _velocity
	sta     _velocity
	bcc     L4C86
	inc     _velocity+1
;
; if(velocity > 720){
;
L4C86:	lda     _velocity
	cmp     #$D1
	lda     _velocity+1
	sbc     #$02
	lda     #$00
	bcc     L51B0
;
; velocity = 720;
;
	ldx     #$02
	lda     #$D0
	sta     _velocity
	stx     _velocity+1
;
; time_since_button_press = 0;
;
	lda     #$00
L51B0:	sta     _time_since_button_press
;
; steps++;
;
	lda     _steps
	ldx     _steps+1
	clc
	adc     #$01
	bcc     L4C8E
	inx
L4C8E:	sta     _steps
	stx     _steps+1
;
; if(progress_pixels < 212){
;
	lda     _progress_pixels
	cmp     #$D4
	bcs     L51B1
;
; progress_remainder += 212;
;
	lda     #$D4
	clc
	adc     _progress_remainder
	sta     _progress_remainder
	bcc     L4C93
	inc     _progress_remainder+1
;
; if(progress_remainder >= total_steps_needed){
;
L4C93:	lda     _progress_remainder
	cmp     _total_steps_needed
	lda     _progress_remainder+1
	sbc     _total_steps_needed+1
	bcc     L51B1
;
; progress_remainder -= total_steps_needed;
;
	lda     _total_steps_needed
	eor     #$FF
	sec
	adc     _progress_remainder
	sta     _progress_remainder
	lda     _total_steps_needed+1
	eor     #$FF
	adc     _progress_remainder+1
	sta     _progress_remainder+1
;
; ++progress_pixels;
;
	inc     _progress_pixels
;
; step_button_lockout = FRAMES_PER_STEP; //lock out for a few frames to avoid double counting
;
L51B1:	lda     #$0A
	sta     _step_button_lockout
;
; if(ones_step == 9){
;
	lda     _ones_step
	cmp     #$09
	bne     L51B6
;
; ones_step = 0;
;
	lda     #$00
	sta     _ones_step
;
; if(tens_step == 9){
;
	lda     _tens_step
	cmp     #$09
	bne     L51B5
;
; tens_step = 0;
;
	lda     #$00
	sta     _tens_step
;
; if(hundreds_step == 9){
;
	lda     _hundreds_step
	cmp     #$09
	bne     L51B4
;
; hundreds_step = 0;
;
	lda     #$00
	sta     _hundreds_step
;
; if(thousands_step == 9){
;
	lda     _thousands_step
	cmp     #$09
	bne     L51B3
;
; thousands_step = 0;
;
	lda     #$00
	sta     _thousands_step
;
; if(ten_thousands_step == 9){
;
	lda     _ten_thousands_step
	cmp     #$09
	bne     L51B2
;
; ten_thousands_step = 0;
;
	lda     #$00
	sta     _ten_thousands_step
;
; } else {
;
	rts
;
; ten_thousands_step++;
;
L51B2:	inc     _ten_thousands_step
;
; } else {
;
	rts
;
; thousands_step++;
;
L51B3:	inc     _thousands_step
;
; } else {
;
	rts
;
; hundreds_step++;
;
L51B4:	inc     _hundreds_step
;
; } else {
;
	rts
;
; tens_step++;
;
L51B5:	inc     _tens_step
;
; } else {
;
	rts
;
; ones_step++;
;
L51B6:	inc     _ones_step
;
; }
;
	rts

.endproc

